import { useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import type { DatosClinica, Equipo, EquipoBorrador, Estado, Propietario, RespuestaChecklist, Rol, Servicio, UsuarioSesion } from './types';
import { ALUMNOS, NOMBRE_ESTADO, NOMBRE_SERVICIO, fechaLegible } from './data';
import { autenticar } from './auth-demo';
import { generarCodigo, guardarDatos, guardarSesion, leerDatos, leerSesion } from './store';
import { formatearRut, limpiarRut, rutValido } from './rut';
import { SERVICIOS, nombreServicios, filtrarEquipos, crearRespuestas, respuestasValidas, evento, puedeAnular, crearCorreoDemo, asegurarBasico, actualizarEspecializados, agregarActividad, editarActividad, quitarActividad, asignarOrden, enlaceContacto } from './clinica';

type Pantalla = 'inicio'|'registro'|'consulta'|'login'|'panel'|'comprobante'|'encuesta';
type TabAlumno = 'equipos'|'ficha'|'historial';
type Tab = 'equipos'|'registro'|'qr'|'plantillas'|'estudiantes'|'avisos';
type Filtro = 'todos'|'pendientes'|'en_atencion'|'listos'|'cerrados';
const FILTROS:{id:Filtro;nombre:string}[]=[{id:'todos',nombre:'Todos'},{id:'pendientes',nombre:'Pendientes'},{id:'en_atencion',nombre:'En atención'},{id:'listos',nombre:'Listos para retirar'},{id:'cerrados',nombre:'Cerrados y anulados'}];
const NUEVO:EquipoBorrador={tipo:'',marca:'',modelo:'',serie:'',servicios:[],detalle:''};
const FORM_INICIAL={nombre:'',rut:'',telefono:'',correo:'',consentimiento:false};
const uid=()=>crypto.randomUUID();
const now=()=>new Date().toISOString();
const PRIVACIDAD='Prototipo académico: utiliza exclusivamente datos ficticios. Los datos quedan en el navegador actual y no se comparten entre computadores. Los permisos y credenciales NO son seguros para producción.';

function Campo({titulo,obligatorio=false,children}:{titulo:string;obligatorio?:boolean;children:ReactNode}){return <label className="campo"><span className="etiqueta">{titulo}{obligatorio&&<span className="required"> *</span>}</span>{children}</label>}
function EstadoChip({estado}:{estado:Estado}){return <span className={`estado estado-${estado}`}>{NOMBRE_ESTADO[estado]}</span>}
function ServicioChips({servicios}:{servicios:Servicio[]}){return <div className="chips">{servicios.map(s=><span className="chip" key={s}>{NOMBRE_SERVICIO[s]}</span>)}</div>}
function Aviso({children}:{children:ReactNode}){return <div className="alerta-informativa" role="note">🔒 {children}</div>}
function Titulo({kicker,titulo,descripcion}:{kicker:string;titulo:string;descripcion?:string}){return <div className="titulo-pagina"><span className="mini-label">{kicker}</span><h1>{titulo}</h1>{descripcion&&<p>{descripcion}</p>}</div>}
function ControlServicio({seleccionados,alCambiar,modo='checkbox'}:{seleccionados:Servicio[];alCambiar:(servicios:Servicio[])=>void;modo?:string}){
  return <fieldset className="radio-fieldset"><legend>{modo==='checkbox'?'Mantenimientos solicitados (puedes marcar varios)':'Checklists especializados (opcional)'} {modo==='checkbox'&&<span className="required">*</span>}</legend>
  {SERVICIOS.map(s=><label key={s} className={`radio-opcion ${seleccionados.includes(s)?'radio-seleccionada':''}`}><input type="checkbox" checked={seleccionados.includes(s)} onChange={e=>alCambiar(e.target.checked?[...seleccionados,s]:seleccionados.filter(x=>x!==s))}/><span><strong>{NOMBRE_SERVICIO[s]}</strong><small>{s==='formateo'?'Reinstalación autorizada del sistema':s==='logica'?'Diagnóstico y optimización de software':'Limpieza e inspección de componentes'}</small></span></label>)}
  </fieldset>
}
function SelectorAlumno({datos,value,onChange}:{datos:DatosClinica;value:string;onChange:(id:string)=>void}){
  const [texto,setTexto]=useState('');
  const elegido=ALUMNOS.find(a=>a.id===value);
  const candidatos=ALUMNOS.filter(a=>a.nombre.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(texto.trim().toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'')));
  return <div className="selector-alumno">{elegido?<div className="alumno-elegido"><span><strong>{elegido.nombre}</strong><small>Estudiante seleccionado</small></span><button type="button" className="enlace-accion" onClick={()=>{onChange('');setTexto('')}}>Cambiar ×</button></div>:<><label className="campo"><span className="etiqueta">Buscar estudiante (opcional)</span><input value={texto} onChange={e=>setTexto(e.target.value)} placeholder="Ej. ale"/></label><div className="candidatos">{candidatos.map(a=><button type="button" key={a.id} className="candidato" onClick={()=>{onChange(a.id);setTexto('')}}><span>{a.nombre}</span><small>{datos.equipos.filter(e=>e.tecnicoId===a.id&&!['entregado','anulado'].includes(e.estado)).length} activas</small></button>)}{!candidatos.length&&<p className="sin-registros">Sin coincidencias.</p>}</div></>}</div>;
}
function FormRegistro({interno,datos,onGuardar,actor="Recepción"}:{interno:boolean;datos:DatosClinica;actor?:string;onGuardar:(d:DatosClinica,codigos:string[])=>void}){
  const [cliente,setCliente]=useState(FORM_INICIAL);const [actual,setActual]=useState<EquipoBorrador>(NUEVO);
  const [extras,setExtras]=useState<EquipoBorrador[]>([]);const [error,setError]=useState('');
  function validarEquipo(e:EquipoBorrador):string {
    if(!e.tipo)return 'Debes seleccionar el tipo de equipo.';
    if(e.marca.trim().length<2||e.marca.trim().length>60)return 'La marca debe tener entre 2 y 60 caracteres.';
    if(e.modelo.trim().length<2||e.modelo.trim().length>80)return 'El modelo debe tener entre 2 y 80 caracteres.';
    if(e.servicios.length===0)return 'Debes seleccionar al menos un mantenimiento.';
    if(e.serie.length>70||e.detalle.length>500)return 'Revisa los límites del número de serie o detalles.';
    return '';
  }
  function agregar(){const err=validarEquipo(actual);if(err){setError(err);return;}setExtras(p=>[...p,{...actual,servicios:[...actual.servicios]}]);setActual(NUEVO);setError('');}
  function registrar(ev:FormEvent){ev.preventDefault();setError('');
    const nombre=cliente.nombre.trim().replace(/\s+/g,' ');
    if(nombre.length<5||nombre.length>100){setError('Escribe el nombre completo (5 a 100 caracteres).');return;}
    if(!rutValido(cliente.rut)){setError('El RUT no es válido. Comprueba el dígito verificador.');return;}
    const telefono=cliente.telefono.replace(/[\s()-]/g,'');
    if(!/^(\+?56)?9\d{8}$/.test(telefono)){setError('El teléfono debe ser un móvil chileno válido, por ejemplo +56 9 1234 5678.');return;}
    const correo=cliente.correo.trim();
    if(correo&&(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo)||correo.length>120)){setError('El correo electrónico no es válido.');return;}
    if(!interno&&!cliente.consentimiento){setError('Debes aceptar el aviso de tratamiento de datos para completar la inscripción en línea.');return;}
    const tieneActual=Boolean(actual.tipo||actual.marca||actual.modelo||actual.serie||actual.detalle||actual.servicios.length);
    if(tieneActual){const err=validarEquipo(actual);if(err){setError(err);return;}}
    const borradores=[...extras,...(tieneActual?[actual]:[])];if(!borradores.length){setError('Debes registrar por lo menos un dispositivo.');return;}
    const existente=datos.propietarios.find(p=>limpiarRut(p.rut)===limpiarRut(cliente.rut));
    if(existente&&existente.nombre.trim().toLocaleLowerCase('es')!==nombre.toLocaleLowerCase('es')){setError('Este RUT ya está registrado con un nombre diferente. Recepción debe verificarlo.');return;}
    const prop:Propietario=existente||{id:uid(),nombre,rut:formatearRut(cliente.rut),telefono,correo,registradoEn:now(),consentimiento:!interno,origenRegistro:interno?'recepcion':'publico'};
    const nuevos:Equipo[]=borradores.map(b=>{const base:Equipo={id:generarCodigo(),propietarioId:prop.id,tipo:b.tipo as Equipo['tipo'],marca:b.marca.trim(),modelo:b.modelo.trim(),serie:b.serie.trim(),servicio:b.servicios[0],serviciosSolicitados:[...b.servicios],serviciosTecnicos:[],detalle:b.detalle.trim(),estado:interno?'recepcionado':'registrado',creadoEn:now(),tecnicoId:null,checklist:[],completadas:[],respuestas:[],relatoCliente:'',observaciones:'',historial:[{fecha:now(),actor:interno?actor:'Inscripción pública',descripcion:interno?'Registro presencial y recepción del equipo':'Inscripción pública mediante enlace o QR'}]};const tecnico=interno?ALUMNOS.find(a=>a.id===b.tecnicoId):undefined;return tecnico?asignarOrden(base,tecnico,actor):base;});
    onGuardar({...datos,propietarios:existente?datos.propietarios:[...datos.propietarios,prop],equipos:[...datos.equipos,...nuevos]},nuevos.map(x=>x.id));
  }
  return <div className="form-layout"><form className="panel panel-form" onSubmit={registrar} noValidate>
    <div className="form-section-title"><span className="seccion-num">01</span><div><h2>Datos del propietario</h2><p>Información para registrar y gestionar la atención.</p></div></div>
    <div className="dos-columnas">
      <Campo titulo="Nombre completo" obligatorio><input value={cliente.nombre} onChange={e=>setCliente({...cliente,nombre:e.target.value})} maxLength={100} placeholder="María González Soto"/></Campo>
      <Campo titulo="RUT" obligatorio><input value={cliente.rut} onChange={e=>setCliente({...cliente,rut:e.target.value})} onBlur={()=>setCliente(x=>({...x,rut:rutValido(x.rut)?formatearRut(x.rut):x.rut}))} maxLength={16} placeholder="12.345.678-5"/></Campo>
      <Campo titulo="Teléfono móvil" obligatorio><input value={cliente.telefono} onChange={e=>setCliente({...cliente,telefono:e.target.value})} maxLength={25} placeholder="+56 9 1234 5678"/></Campo>
      <Campo titulo="Correo para encuesta (opcional)"><input type="email" value={cliente.correo} onChange={e=>setCliente({...cliente,correo:e.target.value})} maxLength={120} placeholder="correo@ejemplo.cl"/></Campo>
    </div>
    <div className="separador"/>
    <div className="form-section-title"><span className="seccion-num">02</span><div><h2>Datos del dispositivo</h2><p>Es posible inscribir más de un equipo y pedir varios servicios.</p></div></div>
    {extras.length>0&&<div className="extras"><strong>{extras.length} equipo(s) agregado(s)</strong>{extras.map((b,i)=><div key={i} className="extra-item"><span>{b.marca} {b.modelo} · {nombreServicios(b.servicios)}{interno&&<small className="tabla-secundaria">{ALUMNOS.find(a=>a.id===b.tecnicoId)?.nombre||'Pendiente de asignación'}</small>}</span><button type="button" onClick={()=>setExtras(p=>p.filter((_,j)=>j!==i))}>Quitar</button></div>)}</div>}
    <div className="dos-columnas">
      <Campo titulo="Tipo" obligatorio><select value={actual.tipo} onChange={e=>setActual({...actual,tipo:e.target.value as EquipoBorrador['tipo']})}><option value="">Seleccionar</option><option value="notebook">Notebook</option><option value="escritorio">PC escritorio</option></select></Campo>
      <Campo titulo="Marca" obligatorio><input value={actual.marca} maxLength={60} onChange={e=>setActual({...actual,marca:e.target.value})} placeholder="Lenovo"/></Campo>
      <Campo titulo="Modelo" obligatorio><input value={actual.modelo} maxLength={80} onChange={e=>setActual({...actual,modelo:e.target.value})} placeholder="IdeaPad 3"/></Campo>
      <Campo titulo="Número de serie"><input value={actual.serie} maxLength={70} onChange={e=>setActual({...actual,serie:e.target.value})} placeholder="Opcional"/></Campo>
    </div>
    <ControlServicio seleccionados={actual.servicios} alCambiar={servicios=>setActual({...actual,servicios})}/>
    <Campo titulo="Detalles y síntomas informados"><textarea value={actual.detalle} maxLength={500} rows={3} onChange={e=>setActual({...actual,detalle:e.target.value})} placeholder="Describe qué ocurre con el equipo..."/></Campo>
    {interno&&<section className="asignacion-registro"><div className="form-section-title"><span className="seccion-num">03</span><div><h2>Asignación del dispositivo</h2><p>Elige quién lo atenderá ahora o déjalo sin asignar.</p></div></div><SelectorAlumno key={extras.length} datos={datos} value={actual.tecnicoId||''} onChange={tecnicoId=>setActual({...actual,tecnicoId})}/></section>}
    <button type="button" className="boton boton-add" onClick={agregar}>＋ Agregar otro dispositivo</button>
    <div className="separador"/>
    {interno?<div className="alerta-informativa"><strong>Registro presencial:</strong> no se muestra la casilla de consentimiento del formulario público, según el flujo solicitado. Recepción debe informar al propietario sobre el tratamiento de datos y documentar las autorizaciones y requisitos legales aplicables fuera de esta simulación.</div>:
      <label className="consentimiento"><input type="checkbox" checked={cliente.consentimiento} onChange={e=>setCliente({...cliente,consentimiento:e.target.checked})}/><span>He leído el aviso de privacidad de este prototipo y autorizo el uso de <strong>datos ficticios</strong> para gestionar mi solicitud. Esto no autoriza por sí solo acceder a archivos privados ni formatear el equipo.</span></label>}
    {error&&<div className="error" role="alert">{error}</div>}
    <button type="submit" className="boton boton-rojo boton-bloque">{interno?(actual.tecnicoId||extras.some(x=>x.tecnicoId)?'Registrar y asignar equipos':'Registrar sin asignar'):'Registrar solicitud'} →</button>
  </form><aside className="aside-form"><div className="panel ayuda"><h3>Información de registro</h3><div className="ayuda-item"><span>01</span><p>Un propietario puede registrar varios dispositivos.</p></div><div className="ayuda-item"><span>02</span><p>Cada dispositivo recibe un código de atención diferente.</p></div><div className="ayuda-item"><span>03</span><p>El técnico puede seleccionar otros checklists según el diagnóstico.</p></div></div><div className="aside-privacidad">⚠ {PRIVACIDAD}</div></aside></div>;
}

declare global {interface Window{ClinicaQr?:{make:(url:string)=>boolean[][]}}}
function QrRegistro(){
  const enlace=window.location.origin+window.location.pathname+'?registro=1';
  const matriz=useMemo(()=>{try{return window.ClinicaQr?.make(enlace)||null;}catch{return null;}},[enlace]);
  const size=matriz?.length||0;
  return <div className="qr-layout"><div className="qr-cuadro">{matriz?<svg role="img" aria-label="Código QR del enlace al formulario" viewBox={`-4 -4 ${size+8} ${size+8}`} width="286" height="286" shapeRendering="crispEdges"><rect x="-4" y="-4" width={size+8} height={size+8} fill="white"/>{matriz.flatMap((r,y)=>r.map((v,x)=>v?<rect key={`${x}-${y}`} x={x} y={y} width="1" height="1" fill="#171719"/>:null))}</svg>:<p>No se pudo generar el QR.</p>}</div>
    <div className="qr-contenido"><h3>Inscripción por QR</h3><p>La recepcionista puede mostrar este código en pantalla o imprimirlo. Al escanearlo se abre directamente el formulario público para el propietario.</p>
      <div className="campo"><span className="etiqueta">Enlace del formulario</span><input value={enlace} readOnly aria-label="Enlace para inscripción"/></div>
      <div className="fila-botones"><button className="boton boton-rojo" onClick={()=>void navigator.clipboard?.writeText(enlace)}>Copiar enlace</button><button className="boton boton-outline" onClick={()=>window.print()}>Imprimir QR</button></div>
      <div className="alerta-informativa"><strong>Recomendación:</strong> Ubique el código QR en un lugar visible y de fácil acceso para facilitar la inscripción de los clientes durante la jornada de atención.</div>
    </div>
  </div>;
}

function Tarjeta({titulo,valor,detalle}:{titulo:string;valor:number;detalle?:string}){return <div className="metrica"><span>{titulo}</span><strong>{valor}</strong><small>{detalle||'Clínica del PC'}</small></div>}
function Tabla({equipos,datos,ver,rapida}:{equipos:Equipo[];datos:DatosClinica;ver:(id:string)=>void;rapida?:(equipo:Equipo,id:string)=>boolean}){
  const [orden,setOrden]=useState<string|null>(null);const [tecnico,setTecnico]=useState('');
  return <div className="tabla-wrapper"><table className="tabla"><thead><tr><th>Orden</th><th>Cliente</th><th>Equipo</th><th>Solicitado</th><th>Estado / técnico</th><th>Acciones</th></tr></thead><tbody>{equipos.map(e=>{const p=datos.propietarios.find(x=>x.id===e.propietarioId);return <tr key={e.id}><td className="orden-num">{e.id}</td><td>{p?.nombre||'—'}<small className="tabla-secundaria">{p?.rut||''}</small></td><td>{e.marca} {e.modelo}</td><td><ServicioChips servicios={e.serviciosSolicitados}/></td><td><EstadoChip estado={e.estado}/><small className="tabla-secundaria">{ALUMNOS.find(a=>a.id===e.tecnicoId)?.nombre||'Sin asignar'}</small></td><td><div className="acciones-tabla">{rapida&&['registrado','recepcionado'].includes(e.estado)&&<button className="boton boton-rojo boton-small" onClick={()=>{setOrden(e.id);setTecnico('')}}>{e.estado==='registrado'?'Recibir y asignar':'Asignar estudiante'}</button>}<button className="enlace-accion" onClick={()=>ver(e.id)}>Ver ficha →</button></div></td></tr>})}</tbody></table>{equipos.length===0&&<div className="sin-registros">No hay dispositivos que coincidan con esta búsqueda o etapa.</div>}
  {rapida&&orden&&(()=>{const e=equipos.find(x=>x.id===orden);if(!e||!['registrado','recepcionado'].includes(e.estado))return null;return <div className="modal-fondo" onClick={()=>setOrden(null)}><section role="dialog" aria-modal="true" aria-label="Asignación rápida" className="modal-asignar" onClick={ev=>ev.stopPropagation()}><div className="fila-entre"><div><span className="mini-label">{e.id}</span><h2>{e.marca} {e.modelo}</h2></div><button className="boton boton-outline boton-small" onClick={()=>setOrden(null)}>Cerrar ×</button></div><p className="subtexto">{e.estado==='registrado'?'Confirma que recibiste físicamente el dispositivo y elige un estudiante.':'Selecciona al estudiante que realizará la mantención.'}</p><SelectorAlumno key={e.id} datos={datos} value={tecnico} onChange={setTecnico}/><div className="fila-botones"><button className="boton boton-rojo" disabled={!tecnico} onClick={()=>{if(rapida(e,tecnico))setOrden(null)}}>{e.estado==='registrado'?'Confirmar recepción y asignar':'Confirmar asignación'}</button><button className="boton boton-outline" onClick={()=>setOrden(null)}>Cancelar</button></div></section></div>})()}
  </div>;
}
function tituloGrupo(r:RespuestaChecklist){return r.servicio==='basico'?'Checklist básico':r.servicio==='personalizado'?'Actividad personalizada':NOMBRE_SERVICIO[r.servicio];}
function ChecklistTecnico({equipo,onRespuesta,onAgregar,onEditar,onQuitar}:{equipo:Equipo;onRespuesta:(id:string,cambio:Partial<RespuestaChecklist>)=>void;onAgregar:(t:string)=>boolean;onEditar:(id:string,t:string)=>boolean;onQuitar:(id:string)=>void}){
  const [nuevo,setNuevo]=useState('');const [agregar,setAgregar]=useState(false);const [editar,setEditar]=useState<string|null>(null);const [texto,setTexto]=useState('');
  const completo=equipo.respuestas.filter(r=>r.resultado&&r.observacion.trim().length>=5).length;
  return <section className="caja-accion checklist-v6"><div className="fila-entre wrap checklist-head"><div><span className="mini-label">VERIFICACIONES TÉCNICAS</span><h3>Checklist de mantenimiento</h3></div><strong className="progreso-texto">{completo} / {equipo.respuestas.length} completos</strong></div><progress max={equipo.respuestas.length||1} value={completo}/><p>Responde cada actividad con Sí, No o N/A (no aplica). Añade una observación de al menos 5 caracteres.</p>
    <div className="evaluaciones">{equipo.respuestas.map((r,i)=><div className="evaluacion evaluacion-v6" key={r.id}><div className="evaluacion-encabezado"><span className="seccion-num">{i+1}</span><div><small className="mini-label">{tituloGrupo(r)}</small><strong>{r.tarea}</strong></div>{r.servicio==='personalizado'&&<div className="acciones-personalizadas"><button className="enlace-accion" onClick={()=>{setEditar(r.id);setTexto(r.tarea)}}>Editar</button><button className="enlace-accion" onClick={()=>{if(window.confirm('¿Eliminar esta actividad personalizada y su respuesta?'))onQuitar(r.id)}}>Quitar</button></div>}</div>
    {editar===r.id&&<form className="edicion-actividad" onSubmit={ev=>{ev.preventDefault();if(onEditar(r.id,texto))setEditar(null)}}><Campo titulo="Editar actividad"><input autoFocus value={texto} onChange={ev=>setTexto(ev.target.value)} maxLength={140}/></Campo><small>Al cambiar el texto, se reinicia la respuesta de esta actividad.</small><div className="fila-botones"><button className="boton boton-rojo boton-small" type="submit">Guardar cambio</button><button className="boton boton-outline boton-small" type="button" onClick={()=>setEditar(null)}>Cancelar</button></div></form>}
    <div className="evaluacion-controles"><fieldset className="resultado-opciones"><legend>Resultado *</legend><div>{([{v:'si',t:'Sí'},{v:'no',t:'No'},{v:'no_aplica',t:'N/A'}] as const).map(o=><label key={o.v} className={r.resultado===o.v?'resultado-activo':''}><input type="radio" name={`resultado-${r.id}`} checked={r.resultado===o.v} onChange={()=>onRespuesta(r.id,{resultado:o.v})}/><span>{o.t}</span></label>)}</div></fieldset><Campo titulo="Observación breve" obligatorio><textarea rows={2} maxLength={250} value={r.observacion} onChange={ev=>onRespuesta(r.id,{observacion:ev.target.value})} placeholder="Escribe qué se verificó o por qué no aplica..."/></Campo></div></div>)}</div>
    {agregar?<form className="nueva-actividad" onSubmit={ev=>{ev.preventDefault();if(onAgregar(nuevo)){setNuevo('');setAgregar(false)}}}><Campo titulo="Nueva actividad personalizada" obligatorio><input autoFocus value={nuevo} maxLength={140} onChange={ev=>setNuevo(ev.target.value)} placeholder="Ej. Se realizó limpieza de ventiladores"/></Campo><div className="fila-botones"><button type="button" className="boton boton-outline boton-small" onClick={()=>{setAgregar(false);setNuevo('')}}>Cancelar</button><button className="boton boton-rojo" type="submit" disabled={nuevo.trim().length<5}>Agregar actividad ↵</button></div></form>:<div className="agregar-derecha"><button className="boton boton-outline" onClick={()=>setAgregar(true)}>＋ Agregar actividad</button></div>}
  </section>;
}
function ContactoDemo({equipo,prop,onRegistrar}:{equipo:Equipo;prop:Propietario|null|undefined;onRegistrar:(canal:string)=>boolean}){
 const [canal,setCanal]=useState<'WhatsApp'|'Correo'|null>(null);const [mensaje,setMensaje]=useState('');const [hecho,setHecho]=useState(false);
 const url=canal?enlaceContacto(canal,canal==='WhatsApp'?(prop?.telefono||''):(prop?.correo||''),mensaje,equipo.id):null;
 const abrir=(c:'WhatsApp'|'Correo')=>{setCanal(c);setHecho(false);setMensaje(`Hola, le escribe el equipo técnico de la Clínica del PC de INACAP por la orden ${equipo.id}. Necesitamos consultar algunos detalles sobre su equipo ${equipo.marca} ${equipo.modelo}.`);};
 return <section className="contacto-v6"><div><span className="mini-label">COMUNICACIÓN</span><h3>Contactar al propietario</h3><p>Prepara consultas por WhatsApp o correo. Puedes simularlas sin enviar nada. No solicites contraseñas ni información sensible.</p></div><div className="fila-botones"><button className="boton boton-whatsapp" disabled={!prop?.telefono} onClick={()=>abrir('WhatsApp')}>WhatsApp · consulta</button><button className="boton boton-outline" disabled={!prop?.correo} onClick={()=>abrir('Correo')}>Correo · consulta</button></div>{!prop?.correo&&<small className="subtexto">El propietario no registró correo.</small>}
 {canal&&<div className="contacto-borrador"><div className="fila-entre"><strong>{canal} · Borrador de demostración</strong><button className="enlace-accion" onClick={()=>setCanal(null)}>Cerrar ×</button></div><Campo titulo="Mensaje"><textarea rows={4} value={mensaje} maxLength={600} onChange={e=>{setMensaje(e.target.value);setHecho(false)}}/></Campo><div className="fila-botones"><button className="boton boton-rojo boton-small" disabled={hecho||mensaje.trim().length<10} onClick={()=>{if(onRegistrar(canal))setHecho(true)}}>Simular contacto</button><button className="boton boton-outline boton-small" onClick={()=>void navigator.clipboard?.writeText(mensaje)}>Copiar texto</button>{url&&<button className="boton boton-outline boton-small" disabled={mensaje.trim().length<10} onClick={()=>{if(window.confirm('Se abrirá una aplicación externa con el destinatario y el texto preparado. No se envía automáticamente. Para la evaluación utiliza solo Simular contacto. ¿Deseas continuar?')){if(canal==='WhatsApp')window.open(url,'_blank','noopener,noreferrer');else window.location.href=url;}}}>Abrir {canal} (externo)</button>}</div>{hecho&&<p role="status" className="exito-inline">Contacto registrado en el historial. No se envió ningún mensaje real.</p>}</div>}</section>;
}


export default function App(){
  const q=new URLSearchParams(window.location.search);
  const [pantalla,setPantalla]=useState<Pantalla>(()=>q.has('encuesta')?'encuesta':q.has('registro')?'registro':leerSesion()?'panel':'inicio');
  const [sesion,setSesion]=useState<UsuarioSesion|null>(leerSesion);
  const [datos,setDatos]=useState<DatosClinica>(leerDatos);
  const [tab,setTab]=useState<Tab>('equipos');const [tabAlumno,setTabAlumno]=useState<TabAlumno>('equipos');const [fichaId,setFichaId]=useState<string|null>(null);
  const [busqueda,setBusqueda]=useState('');const [filtro,setFiltro]=useState<Filtro>('todos');
  const [loginUsuario,setLoginUsuario]=useState('');const [loginClave,setLoginClave]=useState('');const [loginError,setLoginError]=useState('');
  const [codigos,setCodigos]=useState<string[]>([]);const [codigoConsulta,setCodigoConsulta]=useState('');const [rutConsulta,setRutConsulta]=useState('');const [consultaError,setConsultaError]=useState('');const [consultaId,setConsultaId]=useState<string|null>(null);
  const [aviso,setAviso]=useState('');const [buscarAlumno,setBuscarAlumno]=useState('');const [alumnoElegido,setAlumnoElegido]=useState('');
  const [anularId,setAnularId]=useState<string|null>(null);const [motivoAnular,setMotivoAnular]=useState('');const [confirmarEntrega,setConfirmarEntrega]=useState(false);
  const [plantillaActiva,setPlantillaActiva]=useState<Servicio>('logica');const [nuevaTarea,setNuevaTarea]=useState('');
  const [nombreEditar,setNombreEditar]=useState(''); const [serieEditar,setSerieEditar]=useState('');
  const [puntaje,setPuntaje]=useState(5);const [encuestaNota,setEncuestaNota]=useState('');const [encuestaCompleta,setEncuestaCompleta]=useState(false);
  const ficha=datos.equipos.find(e=>e.id===fichaId)||null;
  const propFicha=ficha?datos.propietarios.find(p=>p.id===ficha.propietarioId):null;
  const equiposAlumno=datos.equipos.filter(e=>e.tecnicoId===sesion?.id&&e.estado!=='anulado');
  const listado=filtrarEquipos(datos,busqueda,filtro);
  const tokenEncuesta=new URLSearchParams(window.location.search).get('encuesta');
  const equipoEncuesta=datos.equipos.find(e=>e.encuestaToken&&e.encuestaToken===tokenEncuesta);
  const notificados=datos.equipos.filter(e=>e.correoSimulado);

  function guardar(nuevo:DatosClinica){if(!guardarDatos(nuevo)){setAviso('No pudimos guardar la información. Revisa el espacio disponible y la configuración del navegador.');return false;}setDatos(nuevo);setAviso('');return true;}
  function cambiarEquipo(id:string,fn:(e:Equipo)=>Equipo){const nuevo={...datos,equipos:datos.equipos.map(e=>e.id===id?fn(e):e)};return guardar(nuevo);}
  function navegar(p:Pantalla){if(p==='panel'&&!sesion){p='login';}setPantalla(p);setAviso('');window.scrollTo(0,0);}
  function salir(){guardarSesion(null);setSesion(null);setFichaId(null);setTab('equipos');navegar('inicio');}
  async function entrar(e:FormEvent){e.preventDefault();setLoginError('');try{const u=await autenticar(loginUsuario,loginClave);guardarSesion(u);setSesion(u);setLoginClave('');setTab('equipos');setTabAlumno('equipos');setFichaId(null);setBusqueda('');setFiltro('todos');setPantalla('panel');window.scrollTo(0,0);}catch(err){setLoginError(err instanceof Error?err.message:'No se pudo ingresar.');}}
  function terminarRegistro(d:DatosClinica,lista:string[]){if(guardar(d)){setCodigos(lista);setTab('equipos');setFichaId(null);setFiltro('todos');setBusqueda('');navegar('comprobante');}}
  function abrirFicha(id:string){const eq=datos.equipos.find(e=>e.id===id);setNombreEditar(eq?.modelo||'');setSerieEditar(eq?.serie||'');setFichaId(id);setBuscarAlumno('');setAlumnoElegido('');setAnularId(null);setMotivoAnular('');setConfirmarEntrega(false);setAviso('');window.scrollTo({top:400,behavior:'smooth'});}
  function recibir(e:Equipo){if(!sesion||!['recepcionista','profesor'].includes(sesion.rol)||e.estado!=='registrado')return;cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Recepción presencial confirmada','recepcionado'));}
  function asignar(e:Equipo){if(!sesion||!['recepcionista','profesor'].includes(sesion.rol)||e.estado!=='recepcionado')return;const a=ALUMNOS.find(x=>x.id===alumnoElegido);if(!a){setAviso('Selecciona un estudiante de la lista.');return;}if(cambiarEquipo(e.id,x=>evento(x,sesion.nombre,`Atención asignada a ${a.nombre}`,'asignado',{tecnicoId:a.id}))){setBuscarAlumno('');setAlumnoElegido('');}}
  function asignarRapido(e:Equipo,id:string){if(!sesion||!['recepcionista','profesor'].includes(sesion.rol))return false;const a=ALUMNOS.find(x=>x.id===id);if(!a)return false;try{return cambiarEquipo(e.id,x=>asignarOrden(x,a,sesion.nombre));}catch(err){setAviso(err instanceof Error?err.message:'No se pudo asignar.');return false;}}
  function anular(e:Equipo){if(sesion?.rol!=='profesor'||!puedeAnular(e))return;const m=motivoAnular.trim();if(m.length<8||m.length>200){setAviso('Indica un motivo de entre 8 y 200 caracteres.');return;}if(cambiarEquipo(e.id,x=>evento(x,sesion.nombre,`Registro anulado. Motivo: ${m}`,'anulado'))){setAnularId(null);setMotivoAnular('');}}
  function editarEquipo(e:Equipo){if(sesion?.rol!=='profesor'||!['registrado','recepcionado'].includes(e.estado))return;const nombre=nombreEditar.trim(),serie=serieEditar.trim();if(nombre.length<2||nombre.length>80||serie.length>70){setAviso('Modelo de 2–80 caracteres; serie hasta 70 caracteres.');return;}cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Datos técnicos corregidos',x.estado,{modelo:nombre,serie}));setNombreEditar('');}
  function iniciarAtencion(e:Equipo){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='asignado')return;if(e.relatoCliente.trim().length<10){setAviso('Antes de comenzar, escribe lo que explica el cliente (al menos 10 caracteres).');return;}cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Se registró el relato del cliente y comenzó la atención','en_mantenimiento',{respuestas:asegurarBasico(x.respuestas)}));}
  function elegirServiciosTecnicos(e:Equipo,seleccionados:Servicio[]){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='en_mantenimiento')return;
    const perdidos=e.respuestas.filter(r=>SERVICIOS.some(v=>v===r.servicio)&&!seleccionados.some(v=>v===r.servicio)&&(r.resultado||r.observacion.trim()));
    if(perdidos.length&&!window.confirm('Al desmarcar este checklist perderás las respuestas ya registradas para ese servicio. ¿Continuar?'))return;
    cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Selección de checklists especializados actualizada',x.estado,{serviciosTecnicos:seleccionados,respuestas:actualizarEspecializados(x.respuestas,seleccionados,datos.plantillas)}));
  }
  function actividadPersonalizada(e:Equipo,accion:'agregar'|'editar'|'quitar',texto:string,id?:string){
    if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='en_mantenimiento')return false;
    try{const r=accion==='agregar'?agregarActividad(e.respuestas,texto,uid()):accion==='editar'?editarActividad(e.respuestas,id!,texto):quitarActividad(e.respuestas,id!);return cambiarEquipo(e.id,x=>evento(x,sesion.nombre,`Actividad personalizada: ${accion==='agregar'?'agregada':accion==='editar'?'editada':'eliminada'} (${texto||e.respuestas.find(t=>t.id===id)?.tarea||''})`,x.estado,{respuestas:r}));}catch(err){setAviso(err instanceof Error?err.message:'No se pudo modificar la actividad.');return false;}
  }
  function registrarContacto(e:Equipo,canal:string){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||!['asignado','en_mantenimiento','listo'].includes(e.estado))return false;return cambiarEquipo(e.id,x=>evento(x,sesion.nombre,`Consulta por ${canal} simulada (sin envío real)`));}

  function cambiarRespuesta(e:Equipo,id:string,cambio:Partial<RespuestaChecklist>){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='en_mantenimiento')return;cambiarEquipo(e.id,x=>({...x,respuestas:x.respuestas.map(r=>r.id===id?{...r,...cambio}:r)}));}
  function finalizarAtencion(e:Equipo){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='en_mantenimiento')return;
    if(e.relatoCliente.trim().length<10){setAviso('Debes registrar el relato inicial del cliente.');return;}
    if(!respuestasValidas(e.respuestas)){setAviso('Completa cada tarea con Sí, No o No aplica y una observación de 5 caracteres como mínimo.');return;}
    if(e.observaciones.trim().length<15){setAviso('Completa la observación final con al menos 15 caracteres.');return;}
    cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Checklist completo; equipo listo para aviso al propietario','listo'));
  }
  function notificar(e:Equipo){if(sesion?.rol!=='alumno'||e.tecnicoId!==sesion.id||e.estado!=='listo')return;
    const prop=datos.propietarios.find(p=>p.id===e.propietarioId);const token=uid().replace(/-/g,'');
    const nuevo=e;const mensaje=crearCorreoDemo(nuevo,prop?.correo||'');
    const encuestaUrl=window.location.origin+window.location.pathname+'?encuesta='+encodeURIComponent(token);
    cambiarEquipo(e.id,x=>evento(x,sesion.nombre,prop?.correo?'Aviso y encuesta preparados (simulación, no enviado)':'Aviso sin correo registrado; encuesta pendiente (simulación)','notificado',{encuestaToken:token,correoSimulado:{...mensaje,encuestaUrl,mensaje:`Su equipo ${e.marca} ${e.modelo} está listo para retiro. Encuesta de satisfacción: ${encuestaUrl}`}}));
  }
  function cerrarAtencion(e:Equipo){if(sesion?.rol!=='profesor'||e.estado!=='notificado'||!confirmarEntrega)return;const ok=cambiarEquipo(e.id,x=>evento(x,sesion.nombre,'Prueba conjunta con el propietario y entrega confirmadas','entregado'));if(ok)setConfirmarEntrega(false);}
  function enviarEncuesta(ev:FormEvent){ev.preventDefault();if(!equipoEncuesta||equipoEncuesta.encuestaRespondida)return;if(encuestaNota.length>500){setAviso('Máximo 500 caracteres.');return;}if(cambiarEquipo(equipoEncuesta.id,x=>evento(x,'Encuesta pública','Encuesta de satisfacción respondida',x.estado,{encuestaRespondida:{fecha:now(),calificacion:puntaje,comentario:encuestaNota.trim()}}))){setEncuestaCompleta(true);}}
  function consultar(e:FormEvent){e.preventDefault();const eq=datos.equipos.find(x=>x.id.toUpperCase()===codigoConsulta.trim().toUpperCase());const p=datos.propietarios.find(x=>x.id===eq?.propietarioId);
    if(!eq||!p||!rutValido(rutConsulta)||limpiarRut(p.rut)!==limpiarRut(rutConsulta)){setConsultaId(null);setConsultaError('No encontramos una atención que coincida con el código y RUT.');return;}setConsultaId(eq.id);setConsultaError('');
  }

  return <div className="app">
    <header className="cabecera"><div className="contenedor cabecera-interior"><button className="marca" onClick={()=>navegar('inicio')}><img src="/logo-inacap.png" alt="INACAP"/><span className="marca-separador"/><span className="marca-nombre">Clínica del PC<small>Servicio técnico gratuito</small></span></button>
    <nav className="navegacion" aria-label="Navegación principal">{sesion?<><span className="saludo">{sesion.nombre} · {sesion.rol}</span><button className="boton boton-outline boton-small" onClick={()=>navegar('panel')}>Mi panel</button><button className="boton boton-ghost boton-small" onClick={salir}>Cerrar sesión</button></>:<><button className="navegacion-simple" onClick={()=>navegar('consulta')}>Consultar estado</button><button className="boton boton-outline boton-small login-superior" onClick={()=>navegar('login')}>Iniciar sesión ↗</button></>}</nav></div></header>

    {pantalla==='inicio'&&<main><section className="hero"><div className="contenedor hero-grid"><div className="hero-texto"><div className="eyebrow"><span className="punto"/> INICIATIVA DE APOYO A LA COMUNIDAD</div><h1>Tu computador merece una <em>segunda oportunidad.</em></h1><p>Estudiantes de informática de INACAP realizan jornadas de soporte técnico gratuito. Inscribe uno o varios mantenimientos para tu equipo.</p><div className="hero-acciones"><button className="boton boton-rojo boton-grande" onClick={()=>navegar('registro')}>Inscribir mi equipo →</button><button className="boton boton-claro boton-grande" onClick={()=>navegar('consulta')}>Consultar mi solicitud</button></div><div className="hero-note">✓ Inscripción gratuita · ✓ Atención con estudiantes supervisados</div></div><div className="hero-dibujo"><div className="orbit orbit-1"/><div className="orbit orbit-2"/><div className="pc-figura"><div className="pc-pantalla"><div className="pantalla-interior"><div className="linea linea-1"/><div className="linea linea-2"/><div className="linea linea-3"/><div className="escudo">✓</div></div></div><div className="pc-base"/><div className="pc-pie"/></div><div className="tarjeta-flotante tarjeta-f1"><span className="flotante-icon">✓</span><div><strong>Registro en línea</strong><small>Acceso mediante QR</small></div></div><div className="tarjeta-flotante tarjeta-f2"><span className="flotante-icon rojo">⚙</span><div><strong>Mantención gratuita</strong><small>Atención supervisada</small></div></div></div></div></section>
      <section className="servicios contenedor"><div className="section-heading"><div><span className="mini-label">SERVICIOS DISPONIBLES</span><h2>¿Qué necesitas revisar?</h2></div><p>Elige uno o varios servicios; el técnico evaluará los checklists necesarios cuando reciba el equipo.</p></div><div className="tarjetas-servicios">{SERVICIOS.map((s,i)=><article className="servicio" key={s}><span className="servicio-num">0{i+1}</span><div className="servicio-icon">{s==='formateo'?'⟳':s==='logica'?'⚙':'▣'}</div><h3>{NOMBRE_SERVICIO[s]}</h3><p>{s==='formateo'?'Reinstalación autorizada del sistema operativo':s==='logica'?'Revisión y optimización del software':'Limpieza y revisión de componentes'}</p></article>)}</div></section>
      <section className="pasos"><div className="contenedor"><div className="section-heading"><div><span className="mini-label">CÓMO FUNCIONA</span><h2>Tu atención, paso a paso</h2></div></div><div className="pasos-grid">{[['1','Registra','Escanea el QR o abre el formulario.'],['2','Entrega','Recepción valida y asigna el equipo.'],['3','Mantención','El alumno realiza checklists y observaciones.'],['4','Retira','Recibe aviso, responde encuesta y confirma entrega.']].map(x=><div key={x[0]} className="paso"><span>{x[0]}</span><h3>{x[1]}</h3><p>{x[2]}</p></div>)}</div></div></section>
    </main>}

    {pantalla==='registro'&&<main className="pag-interior contenedor"><button className="enlace-volver" onClick={()=>navegar('inicio')}>← Volver al inicio</button><Titulo kicker="INSCRIPCIÓN EN LÍNEA" titulo="Registra tu equipo" descripcion="Solicita uno o más tipos de mantenimiento. No necesitas una cuenta para inscribirte."/><Aviso>{PRIVACIDAD}</Aviso><FormRegistro interno={false} datos={datos} onGuardar={terminarRegistro}/></main>}
    {pantalla==='comprobante'&&<main className="pag-interior contenedor narrow"><div className="panel resultado"><div className="resultado-icon">✓</div><span className="mini-label">REGISTRO EXITOSO</span><h1>¡Registro realizado!</h1><p>{sesion?'La inscripción quedó guardada. Puedes volver a tu panel o registrar otro cliente.':'Guarda tu código por cada dispositivo. El personal de recepción lo utilizará cuando llegues.'}</p><div className="codigos">{codigos.map(c=><div className="codigo" key={c}><span>Código de orden</span><strong>{c}</strong>{sesion&&<small>{ALUMNOS.find(a=>a.id===datos.equipos.find(e=>e.id===c)?.tecnicoId)?.nombre||"Pendiente de asignación"}</small>}<button className="boton boton-outline boton-small" onClick={()=>void navigator.clipboard?.writeText(c)}>Copiar</button></div>)}</div><Aviso>Los datos se guardaron únicamente en este navegador. No se sincronizan con otros dispositivos sin backend.</Aviso><div className="fila-botones"><button className="boton boton-rojo" onClick={()=>navegar(sesion?'panel':'inicio')}>{sesion?'Volver al panel':'Continuar'}</button>{sesion&&sesion.rol!=='alumno'&&<button className="boton boton-outline" onClick={()=>{setTab('registro');navegar('panel')}}>Registrar otro cliente</button>}</div></div></main>}
    {pantalla==='consulta'&&<main className="pag-interior contenedor narrow"><Titulo kicker="CONSULTAR SOLICITUD" titulo="Estado de mi equipo" descripcion="Para consultar, ingresa el código de orden y el RUT registrado."/><form className="panel panel-form" onSubmit={consultar}><Campo titulo="Código de atención" obligatorio><input maxLength={25} value={codigoConsulta} onChange={e=>setCodigoConsulta(e.target.value)} placeholder="OT-..."/></Campo><Campo titulo="RUT" obligatorio><input value={rutConsulta} maxLength={16} onChange={e=>setRutConsulta(e.target.value)} placeholder="12.345.678-5"/></Campo>{consultaError&&<div role="alert" className="error">{consultaError}</div>}<button type="submit" className="boton boton-rojo boton-bloque">Consultar estado</button></form>{consultaId&&(()=>{const eq=datos.equipos.find(e=>e.id===consultaId);return eq?<div className="panel panel-tab seguimiento"><h2>{eq.marca} {eq.modelo}</h2><EstadoChip estado={eq.estado}/><p>Orden: {eq.id}</p><ServicioChips servicios={eq.serviciosSolicitados}/>{eq.correoSimulado&&<p className="subtexto">Se registró un aviso de retiro en la demostración.</p>}</div>:null;})()}</main>}
    {pantalla==='login'&&<main className="pag-interior contenedor login-wrapper"><div className="panel login-panel"><div className="login-avatar">◇</div><span className="mini-label">ACCESO DEL PERSONAL</span><h1>Iniciar sesión</h1><p>Un único formulario para recepcionista, profesor y estudiante. La vista se abre según las credenciales ingresadas.</p><Aviso>Accesos de demostración visibles en el código. No son autenticación segura ni están vinculados a INACAP.</Aviso><form className="login-form" onSubmit={entrar}><Campo titulo="Usuario" obligatorio><input value={loginUsuario} onChange={e=>setLoginUsuario(e.target.value)} placeholder="Correo o ID de estudiante" autoComplete="username" required/></Campo><Campo titulo="Contraseña" obligatorio><input type="password" value={loginClave} onChange={e=>setLoginClave(e.target.value)} autoComplete="current-password" required/></Campo>{loginError&&<div className="error" role="alert">{loginError}</div>}<button type="submit" className="boton boton-rojo boton-bloque">Ingresar a mi panel →</button></form><button className="enlace-volver" onClick={()=>navegar('inicio')}>← Volver al sitio público</button></div></main>}

    {pantalla==='panel'&&sesion&&<main className="dashboard contenedor"><div className="dashboard-encabezado"><div><span className="mini-label">{sesion.rol==='profesor'?'ADMINISTRACIÓN':sesion.rol==='recepcionista'?'RECEPCIÓN DE EQUIPOS':'ÁREA DE MANTENIMIENTO'}</span><h1>Hola, {sesion.nombre.split(' ')[0]} 👋</h1><p>{sesion.rol==='profesor'?'Supervisa atenciones, busca por nombre o RUT y gestiona plantillas.':sesion.rol==='recepcionista'?'Recibe equipos, abre el QR, registra propietarios y asigna estudiantes.':'Revisa tus órdenes, registra lo que informa el cliente y completa las verificaciones.'}</p></div>{['recepcionista','profesor'].includes(sesion.rol)&&<button className="boton boton-rojo" onClick={()=>{setTab('registro');setFichaId(null)}}>＋ Registro presencial</button>}</div>
    {sesion.rol!=='alumno'?<>
      <div className="metricas"><Tarjeta titulo="EQUIPOS REGISTRADOS" valor={datos.equipos.filter(e=>e.estado!=='anulado').length}/><Tarjeta titulo="SIN ASIGNAR" valor={datos.equipos.filter(e=>['registrado','recepcionado'].includes(e.estado)).length}/><Tarjeta titulo="EN ATENCIÓN" valor={datos.equipos.filter(e=>['asignado','en_mantenimiento','revision'].includes(e.estado)).length}/><Tarjeta titulo="LISTOS / AVISADOS" valor={datos.equipos.filter(e=>['listo','notificado'].includes(e.estado)).length}/></div>
      <div className="tabs"><button className={tab==='equipos'?'tab active':'tab'} onClick={()=>{setTab('equipos');setFichaId(null)}}>Dispositivos y clientes</button>
      <button className={tab==='registro'?'tab active':'tab'} onClick={()=>setTab('registro')}>Registro presencial</button>{sesion.rol==='recepcionista'&&<button className={tab==='qr'?'tab active':'tab'} onClick={()=>setTab('qr')}>Mostrar QR</button>}
      {sesion.rol==='profesor'&&<><button className={tab==='plantillas'?'tab active':'tab'} onClick={()=>setTab('plantillas')}>Checklists</button><button className={tab==='estudiantes'?'tab active':'tab'} onClick={()=>setTab('estudiantes')}>Estudiantes</button><button className={tab==='avisos'?'tab active':'tab'} onClick={()=>setTab('avisos')}>Avisos y encuestas</button></>}
      </div>
      {tab==='registro'&&<div className="panel panel-tab"><h2>Registro presencial</h2><p className="subtexto">La recepcionista ingresa los datos sin la casilla de consentimiento del formulario público. Se mantiene el aviso informativo sobre tratamiento de datos.</p><FormRegistro key="recepcion" interno actor={sesion.nombre} datos={datos} onGuardar={terminarRegistro}/></div>}
      {tab==='qr'&&sesion.rol==='recepcionista'&&<div className="panel panel-tab"><h2>QR para clientes</h2><p className="subtexto">Muestra el QR en la entrada o comparte el enlace al formulario público.</p><QrRegistro/></div>}
      {tab==='equipos'&&<div className="panel panel-tab"><div className="fila-entre wrap"><div><h2>Gestión de dispositivos</h2><p className="subtexto">Busca por nombre o RUT del cliente, código de orden, marca o modelo.</p></div></div>
        <div className="filtros"><input value={busqueda} aria-label="Buscar por nombre o RUT" onChange={e=>{setBusqueda(e.target.value);setFichaId(null)}} placeholder="⌕ Nombre, RUT, orden o equipo"/><select value={filtro} aria-label="Filtrar por estado" onChange={e=>{setFiltro(e.target.value as Filtro);setFichaId(null)}}>{FILTROS.map(f=><option key={f.id} value={f.id}>{f.nombre}</option>)}</select></div>
        <div className="filtros-resumen"><span role="status">Mostrando <strong>{listado.length}</strong> de {datos.equipos.length} dispositivos.</span><button className="limpiar-filtros" onClick={()=>{setBusqueda('');setFiltro('todos');setFichaId(null)}}>Limpiar filtros ×</button></div>
        <Tabla equipos={[...listado].reverse()} datos={datos} ver={abrirFicha} rapida={asignarRapido}/>
        {ficha&&<section className="detalle" aria-label="Ficha de atención"><div className="fila-entre wrap"><div><span className="mini-label">ORDEN {ficha.id}</span><h2>{ficha.marca} {ficha.modelo}</h2><ServicioChips servicios={ficha.serviciosSolicitados}/></div><button className="boton boton-outline boton-small" onClick={()=>setFichaId(null)}>Cerrar ficha ×</button></div>
          <div className="detalle-grid"><div><strong>Propietario</strong><span>{propFicha?.nombre||'—'}</span></div><div><strong>RUT</strong><span>{propFicha?.rut||'—'}</span></div><div><strong>Teléfono</strong><span>{propFicha?.telefono||'—'}</span></div><div><strong>Correo</strong><span>{propFicha?.correo||'No registrado'}</span></div><div><strong>Estado</strong><EstadoChip estado={ficha.estado}/></div><div><strong>Estudiante</strong><span>{ALUMNOS.find(a=>a.id===ficha.tecnicoId)?.nombre||'Sin asignar'}</span></div></div>
          {ficha.detalle&&<p className="detalle-problema"><strong>Problema informado en el registro:</strong> {ficha.detalle}</p>}
          {ficha.estado==='registrado'&&<div className="caja-accion"><h3>Recepcionar dispositivo</h3><p>Confirma que el equipo se entregó presencialmente antes de asignarlo.</p><button className="boton boton-rojo" onClick={()=>recibir(ficha)}>Confirmar recepción</button></div>}
          {ficha.estado==='recepcionado'&&<div className="asignar"><h3>Asignar a estudiante</h3><p>Escribe parte del nombre o apellido del alumno. La asignación aparecerá en su cuenta.</p><input value={buscarAlumno} onChange={e=>{setBuscarAlumno(e.target.value);setAlumnoElegido('')}} placeholder="Ej. ale" aria-label="Buscar estudiante"/>
            {buscarAlumno.trim()&&<div className="candidatos">{ALUMNOS.filter(a=>a.nombre.toLocaleLowerCase('es').includes(buscarAlumno.toLocaleLowerCase('es'))).map(a=><button key={a.id} className={alumnoElegido===a.id?'candidato activo':'candidato'} onClick={()=>{setAlumnoElegido(a.id);setBuscarAlumno(a.nombre)}}><span>{a.nombre}</span><small>{datos.equipos.filter(x=>x.tecnicoId===a.id&&!['entregado','anulado'].includes(x.estado)).length} atención(es) activas</small></button>)}</div>}
            <button className="boton boton-rojo" disabled={!alumnoElegido} onClick={()=>asignar(ficha)}>Confirmar asignación</button></div>}
          {ficha.relatoCliente&&<div className="observaciones-admin"><h3>Relato del cliente registrado por el alumno</h3><p>{ficha.relatoCliente}</p></div>}
          {ficha.respuestas.length>0&&<div className="observaciones-admin"><h3>Checklist técnico</h3><ServicioChips servicios={ficha.serviciosTecnicos}/><div className="tabla-wrapper"><table className="tabla"><thead><tr><th>Actividad</th><th>Resultado</th><th>Observación</th></tr></thead><tbody>{ficha.respuestas.map(r=><tr key={r.id}><td>{r.tarea}<small className="tabla-secundaria">{tituloGrupo(r)}</small></td><td>{r.resultado==='si'?'Sí':r.resultado==='no'?'No':r.resultado==='no_aplica'?'No aplica':'Pendiente'}</td><td>{r.observacion||'—'}</td></tr>)}</tbody></table></div></div>}
          {ficha.observaciones&&<div className="observaciones-admin"><h3>Observación final</h3><p>{ficha.observaciones}</p></div>}
          {ficha.correoSimulado&&<div className="alerta-informativa"><strong>Aviso simulado:</strong> {ficha.correoSimulado.canal==='correo_simulado'?`Encuesta preparada para ${ficha.correoSimulado.destinatario}. No se envió un correo real.`:'No hay correo registrado; se requiere contacto por otro medio.'}</div>}
          {ficha.estado==='revision'&&sesion.rol==='profesor'&&<div className="caja-accion"><h3>Orden heredada de la versión anterior</h3><p>La ficha quedó pendiente de revisión. Puedes aprobarla para continuar el flujo.</p><button className="boton boton-rojo" onClick={()=>cambiarEquipo(ficha.id,x=>evento(x,sesion.nombre,'Revisión aprobada','listo'))}>Aprobar revisión</button></div>}
          {ficha.estado==='notificado'&&sesion.rol==='profesor'&&<div className="caja-accion"><h3>Entrega al propietario</h3><label className="consentimiento"><input type="checkbox" checked={confirmarEntrega} onChange={e=>setConfirmarEntrega(e.target.checked)}/><span>Se realizó la prueba conjunta con el propietario antes de la entrega.</span></label><button className="boton boton-rojo" disabled={!confirmarEntrega} onClick={()=>cerrarAtencion(ficha)}>Cerrar atención y confirmar entrega</button></div>}
          {sesion.rol==='profesor'&&['registrado','recepcionado'].includes(ficha.estado)&&<div className="administrar-registro"><h3>Corrección de datos</h3><p className="subtexto">Actualiza modelo y serie antes de asignar. El cambio queda en el historial.</p><div className="dos-columnas"><Campo titulo="Modelo corregido"><input value={nombreEditar} onChange={e=>setNombreEditar(e.target.value)} placeholder={ficha.modelo}/></Campo><Campo titulo="Número de serie"><input value={serieEditar} onChange={e=>setSerieEditar(e.target.value)} placeholder={ficha.serie||'Opcional'}/></Campo></div><button className="boton boton-outline" onClick={()=>editarEquipo(ficha)}>Guardar corrección</button></div>}
          {sesion.rol==='profesor'&&puedeAnular(ficha)&&<div className="administrar-registro zona-peligro"><h3>Anular registro</h3><p>El registro no se borra y queda trazabilidad del motivo.</p>{anularId!==ficha.id?<button className="boton boton-peligro boton-small" onClick={()=>setAnularId(ficha.id)}>Anular registro</button>:<><Campo titulo="Motivo"><textarea maxLength={200} value={motivoAnular} onChange={e=>setMotivoAnular(e.target.value)} placeholder="Ej. inscripción duplicada..."/></Campo><div className="fila-botones"><button className="boton boton-peligro" onClick={()=>anular(ficha)}>Confirmar anulación</button><button className="boton boton-outline" onClick={()=>setAnularId(null)}>Cancelar</button></div></>}</div>}
          <h3 className="historial-titulo">Historial de acciones</h3><div className="historial">{(ficha.historial||[]).slice().reverse().map((h,i)=><div key={i}><span>●</span><p><strong>{h.descripcion}</strong><small>{fechaLegible(h.fecha)} · {h.actor}</small></p></div>)}</div>
        </section>}
      </div>}
      {tab==='estudiantes'&&sesion.rol==='profesor'&&<div className="panel panel-tab"><h2>Estudiantes participantes</h2><p className="subtexto">Cuentas ficticias de prueba. Recepción puede asignar los alumnos utilizando su nombre; cada uno ve solamente sus órdenes al iniciar sesión.</p><div className="tabla-wrapper"><table className="tabla"><thead><tr><th>Nombre</th><th>ID de acceso</th><th>Asignaciones activas</th></tr></thead><tbody>{ALUMNOS.map(a=><tr key={a.id}><td>{a.nombre}</td><td>{a.id}</td><td>{datos.equipos.filter(e=>e.tecnicoId===a.id&&!['entregado','anulado'].includes(e.estado)).length}</td></tr>)}</tbody></table></div></div>}
      {tab==='plantillas'&&sesion.rol==='profesor'&&<div className="panel panel-tab"><h2>Plantillas de checklist configurables</h2><p className="subtexto">Puedes agregar o quitar actividades. Las respuestas guardadas de cada equipo conservan una copia de las tareas originales.</p><div className="plantillas-selector"><label className="etiqueta">Mantenimiento</label><select value={plantillaActiva} onChange={e=>setPlantillaActiva(e.target.value as Servicio)}>{SERVICIOS.map(s=><option value={s} key={s}>{NOMBRE_SERVICIO[s]}</option>)}</select></div><div className="lista-plantilla">{datos.plantillas[plantillaActiva].map((x,i)=><div className="tarea-plantilla" key={i}><span>{i+1}. {x}</span><button onClick={()=>{if(datos.plantillas[plantillaActiva].length<=1){setAviso('Cada plantilla debe tener al menos una actividad.');return;}guardar({...datos,plantillas:{...datos.plantillas,[plantillaActiva]:datos.plantillas[plantillaActiva].filter((_,j)=>j!==i)}})}}>Quitar</button></div>)}</div><div className="agregar-plantilla"><input value={nuevaTarea} maxLength={120} onChange={e=>setNuevaTarea(e.target.value)} placeholder="Escribe nueva actividad..."/><button className="boton boton-rojo" onClick={()=>{const t=nuevaTarea.trim();if(t.length<5){setAviso('La tarea debe tener al menos 5 caracteres.');return;}if(datos.plantillas[plantillaActiva].some(x=>x.toLowerCase()===t.toLowerCase())){setAviso('Esa tarea ya existe.');return;}if(guardar({...datos,plantillas:{...datos.plantillas,[plantillaActiva]:[...datos.plantillas[plantillaActiva],t]}}))setNuevaTarea('')}}>Agregar</button></div></div>}
      {tab==='avisos'&&sesion.rol==='profesor'&&<div className="panel panel-tab"><h2>Avisos y encuestas (simulación)</h2><p className="subtexto">El técnico genera un mensaje y una URL de encuesta, pero no se envía correo real desde el frontend.</p><div className="tabla-wrapper"><table className="tabla"><thead><tr><th>Orden</th><th>Destino</th><th>Fecha</th><th>Encuesta</th></tr></thead><tbody>{notificados.map(e=><tr key={e.id}><td>{e.id}</td><td>{e.correoSimulado?.destinatario}</td><td>{e.correoSimulado&&fechaLegible(e.correoSimulado.fecha)}</td><td>{e.encuestaRespondida?`${e.encuestaRespondida.calificacion}/5`:'Pendiente'}</td></tr>)}</tbody></table>{notificados.length===0&&<div className="sin-registros">Todavía no se generaron avisos.</div>}</div></div>}
    </>:<>
      <div className="metricas"><Tarjeta titulo="MIS ÓRDENES" valor={equiposAlumno.length}/><Tarjeta titulo="POR COMENZAR" valor={equiposAlumno.filter(e=>e.estado==='asignado').length}/><Tarjeta titulo="EN MANTENIMIENTO" valor={equiposAlumno.filter(e=>e.estado==='en_mantenimiento').length}/><Tarjeta titulo="FINALIZADAS" valor={equiposAlumno.filter(e=>['listo','notificado','entregado'].includes(e.estado)).length}/></div>
      <div className="tabs tabs-tecnico" aria-label="Navegación técnica"><button className={tabAlumno==='equipos'?'tab active':'tab'} onClick={()=>setTabAlumno('equipos')}>Mis equipos</button><button className={tabAlumno==='ficha'?'tab active':'tab'} disabled={!ficha||ficha.tecnicoId!==sesion.id} onClick={()=>setTabAlumno('ficha')}>Ficha y checklist</button><button className={tabAlumno==='historial'?'tab active':'tab'} onClick={()=>setTabAlumno('historial')}>Historial</button></div>
      {tabAlumno!=='ficha'&&<div className="panel panel-tab"><h2>{tabAlumno==='equipos'?'Mis equipos asignados':'Historial de mis atenciones'}</h2><p className="subtexto">{tabAlumno==='equipos'?'Abre una orden para comenzar o continuar. Solo se muestran tus equipos.':'Consulta las órdenes finalizadas y su registro técnico.'}</p><div className="mis-ordenes">{equiposAlumno.filter(e=>tabAlumno==='historial'?['listo','notificado','entregado'].includes(e.estado):e.estado!=='entregado').map(e=><button key={e.id} className={`orden-card ${fichaId===e.id?'orden-card-activa':''}`} onClick={()=>{setFichaId(e.id);setTabAlumno('ficha');setAviso('')}}><small className="mini-label">{e.id}</small><strong>{e.marca} {e.modelo}</strong><EstadoChip estado={e.estado}/><span className="enlace-accion">Abrir ficha →</span></button>)}</div>{!equiposAlumno.some(e=>tabAlumno==='historial'?['listo','notificado','entregado'].includes(e.estado):e.estado!=='entregado')&&<div className="sin-registros">{tabAlumno==='equipos'?'No tienes equipos pendientes. Recepción puede asignarte una orden.':'Todavía no tienes órdenes finalizadas.'}</div>}</div>}
      {tabAlumno==='ficha'&&ficha&&ficha.tecnicoId===sesion.id&&ficha.estado!=='anulado'&&<div className="panel panel-tab ficha-tecnica-v6"><div className="fila-entre wrap"><div><span className="mini-label">FICHA TÉCNICA · {ficha.id}</span><h2>{ficha.marca} {ficha.modelo}</h2><EstadoChip estado={ficha.estado}/></div><button className="boton boton-outline boton-small" onClick={()=>setTabAlumno('equipos')}>← Mis equipos</button></div>
        <div className="datos-solicitud"><h3>Servicios solicitados por el cliente</h3><ServicioChips servicios={ficha.serviciosSolicitados}/><p><strong>Problema informado al inscribirse:</strong> {ficha.detalle||'Sin detalles adicionales.'}</p></div>
        {['asignado','en_mantenimiento','listo'].includes(ficha.estado)&&<ContactoDemo key={ficha.id} equipo={ficha} prop={propFicha} onRegistrar={canal=>registrarContacto(ficha,canal)}/>}
        {['asignado','en_mantenimiento'].includes(ficha.estado)&&<div className="caja-accion"><h3>1. Relato inicial del cliente</h3><p>Registra lo que explica el propietario al entregar el equipo. Mínimo 10 caracteres.</p><Campo titulo="Observación inicial"><textarea rows={3} maxLength={1000} value={ficha.relatoCliente} onChange={e=>cambiarEquipo(ficha.id,x=>({...x,relatoCliente:e.target.value}))} placeholder="El cliente explica que..."/></Campo>{ficha.estado==='asignado'&&<button className="boton boton-rojo" disabled={ficha.relatoCliente.trim().length<10} onClick={()=>iniciarAtencion(ficha)}>Iniciar mantenimiento y abrir checklist</button>}</div>}
        {ficha.estado==='en_mantenimiento'&&<><div className="caja-accion"><h3>2. Checklists especializados (opcionales)</h3><p>El checklist básico se carga automáticamente. Agrega especialidades según tu diagnóstico, incluso si el cliente no las solicitó.</p><ControlServicio modo="tecnico" seleccionados={ficha.serviciosTecnicos} alCambiar={v=>elegirServiciosTecnicos(ficha,v)}/></div>
        <ChecklistTecnico key={ficha.id} equipo={ficha} onRespuesta={(id,c)=>cambiarRespuesta(ficha,id,c)} onAgregar={t=>actividadPersonalizada(ficha,'agregar',t)} onEditar={(id,t)=>actividadPersonalizada(ficha,'editar',t,id)} onQuitar={id=>{actividadPersonalizada(ficha,'quitar','',id)}}/>
        <div className="caja-accion"><h3>3. Informe final de mantenimiento</h3><p>Describe lo realizado, lo que no se pudo hacer y recomendaciones. Mínimo 15 caracteres.</p><Campo titulo="Observación final"><textarea rows={5} maxLength={1500} value={ficha.observaciones} onChange={e=>cambiarEquipo(ficha.id,x=>({...x,observaciones:e.target.value}))} placeholder="Se completó la revisión..."/></Campo><div className="fila-botones"><button className="boton boton-rojo" disabled={!respuestasValidas(ficha.respuestas)||ficha.observaciones.trim().length<15||ficha.relatoCliente.trim().length<10} onClick={()=>finalizarAtencion(ficha)}>Finalizar checklist</button><button className="boton boton-outline" onClick={()=>{if(guardar(datos))setTabAlumno('equipos')}}>Guardar y volver</button></div><small className="subtexto">Los cambios se guardan localmente al editar cada campo.</small></div></>}
        {ficha.estado==='listo'&&<div className="caja-accion aviso-retiro"><span className="mini-label">4. AVISO DE RETIRO</span><h3>Equipo listo para retirar</h3><div className="mensaje-preview">Estimado/a cliente: el mantenimiento de su equipo {ficha.marca} {ficha.modelo} ha finalizado. Puede retirarlo en la Clínica del PC de INACAP. Gracias por participar. Se incluirá una encuesta de satisfacción.</div><p>El botón registra el aviso y genera la encuesta de demostración, sin enviar un correo ni WhatsApp real.</p><button className="boton boton-rojo" onClick={()=>notificar(ficha)}>Simular aviso de equipo listo ↗</button></div>}
        {['notificado','entregado'].includes(ficha.estado)&&<div className="alerta-informativa"><strong>{ficha.estado==='entregado'?'Atención entregada y cerrada por el profesor.':'Aviso de retiro registrado (simulación).'}</strong> {ficha.correoSimulado?.canal==='correo_simulado'?'No se envió correo real.':'No se registró un destinatario de correo.'}{ficha.correoSimulado?.encuestaUrl&&<div className="fila-botones"><button className="boton boton-outline boton-small" onClick={()=>void navigator.clipboard?.writeText(ficha.correoSimulado!.encuestaUrl)}>Copiar enlace de encuesta</button></div>}</div>}
        {!['asignado','en_mantenimiento'].includes(ficha.estado)&&<div className="observaciones-admin"><h3>Informe técnico guardado</h3><p><strong>Relato inicial:</strong> {ficha.relatoCliente||'Sin registro previo'}</p><div className="tabla-wrapper"><table className="tabla tabla-informe"><thead><tr><th>Actividad</th><th>Resultado</th><th>Observación</th></tr></thead><tbody>{ficha.respuestas.map(r=><tr key={r.id}><td>{r.tarea}<small className="tabla-secundaria">{tituloGrupo(r)}</small></td><td>{r.resultado==='si'?'Sí':r.resultado==='no'?'No':r.resultado==='no_aplica'?'N/A':'Pendiente'}</td><td>{r.observacion||'—'}</td></tr>)}</tbody></table></div><p><strong>Informe final:</strong> {ficha.observaciones||'Sin registro'}</p></div>}
        <h3 className="historial-titulo">Historial de la orden</h3><div className="historial">{ficha.historial.slice().reverse().map((h,i)=><div key={i}><span>●</span><p><strong>{h.descripcion.replace(/preparados para [^ ]+ \(simulación, no enviado\)/,'preparados (simulación, no enviado)')}</strong><small>{fechaLegible(h.fecha)} · {h.actor}</small></p></div>)}</div>
      </div>}

    </>}
    {aviso&&<div className="error aviso-general" role="alert">{aviso}</div>}
    </main>}

    {pantalla==='encuesta'&&<main className="pag-interior contenedor narrow"><Titulo kicker="ENCUESTA DE SATISFACCIÓN" titulo="Tu opinión nos ayuda" descripcion="Evaluación de atención de la Clínica del PC. Esta encuesta es solo una demostración local."/>{!equipoEncuesta?<div className="panel panel-form"><p>Este enlace de encuesta no existe en los registros de este navegador.</p></div>:equipoEncuesta.encuestaRespondida||encuestaCompleta?<div className="panel panel-form"><h2>¡Gracias por responder!</h2><p>Tu opinión quedó registrada en esta demostración.</p></div>:<form className="panel panel-form" onSubmit={enviarEncuesta}><p>Orden: {equipoEncuesta.id}</p><Campo titulo="¿Cómo calificarías la atención?" obligatorio><select value={puntaje} onChange={e=>setPuntaje(Number(e.target.value))}>{[5,4,3,2,1].map(x=><option key={x} value={x}>{x} de 5</option>)}</select></Campo><Campo titulo="Comentario opcional"><textarea value={encuestaNota} onChange={e=>setEncuestaNota(e.target.value)} rows={3} maxLength={500}/></Campo><button type="submit" className="boton boton-rojo boton-bloque">Enviar encuesta de demostración</button></form>}</main>}
    <footer className="footer"><div className="contenedor footer-interior"><span>Clínica del PC <strong>· INACAP</strong></span><p>Prototipo frontend académico · Sin envío automático real ni autenticación de producción</p><span>Proyecto de demostración</span></div></footer>
  </div>;
}
